<?php
require_once __DIR__.'/../app/helpers.php';require_auth();require_once __DIR__.'/../app/Services/NotificationService.php';$svc=new NotificationService(Database::connection());$uid=(int)auth_user()['id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['all']))$svc->markAllRead($uid);elseif(isset($_POST['id']))$svc->markRead($uid,(int)$_POST['id']);redirect(url('notifications.php'));}$items=$svc->unread($uid,100);$pageTitle=t('Notifications');$currentPage='notifications';require __DIR__.'/partials/header.php';require __DIR__.'/partials/sidebar.php';?><div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><h2><?=e(t('Notifications'))?></h2><form method="post"><?=csrf_field()?><button name="all" value="1" class="btn btn-outline-primary"><?=e(t('Mark all as read'))?></button></form></div><?php if(!$items):?><div class="alert alert-light border"><?=e(t("You're all caught up."))?></div><?php endif;?><?php foreach($items as $n):?><div class="card mb-3 shadow-sm border-0"><div class="card-body"><div class="d-flex justify-content-between"><div><h5><?=e($n['title'])?></h5><p class="mb-1"><?=e($n['message'])?></p><small class="text-muted"><?=e($n['created_at'])?> · <?=e(tx_label($n['channel']))?></small></div><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$n['id']?>"><button class="btn btn-sm btn-outline-secondary"><?=e(t('Mark read'))?></button></form></div></div></div><?php endforeach;?><a href="<?=url('dashboard.php')?>" class="btn btn-link"><?=e(t('Back to dashboard'))?></a></div><?php require __DIR__.'/partials/footer.php';?>
